#!/usr/bin/env python3
import os, base64, zlib
DATA = ""
target = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ict_ob.py")
with open(target, "wb") as f:
    f.write(zlib.decompress(base64.b64decode(DATA)))
print("[OK] ict_ob.py installed ->", target)
print("[OK] ICT Multi-TF OB Confluence Scanner")
print("")
print("Now run:  python ict_ob.py")
